INSERT INTO `guidelines_content` (`id`, `purpose`, `voting_rules`, `how_to_vote`, `privacy_security`, `important_reminders`, `fingerprint_info`, `updated_at`, `updated_by`) VALUES
(1, 'The Student Government Election allows officially enrolled students to select their leaders in a fair, transparent, and secure manner using the online voting system.', '• Each student is allowed to vote only once.\r\n• Votes submitted cannot be changed or canceled.\r\n• Only officially registered and verified students can participate.\r\n• Sharing of accounts or voting on behalf of others is strictly prohibited.', '1. Log in using your registered student account.\r\n2. Go to the Vote section.\r\n3. Select your preferred candidates for each position.\r\n4. Review your choices carefully.\r\n5. Click Submit Vote to finalize your ballot.', 'Your vote is confidential. The system does not display individual voting choices to administrators or other students. All votes are securely stored and counted automatically.\r\n', '• Make sure you have a stable internet connection before voting.\r\n• Do not refresh or close the browser while submitting your vote.\r\n• Report any technical issues immediately to the election committee.\r\n\r\n', 'To enable fingerprint login for faster access, go to your Home Page and register your fingerprint. Once registered, you can log in faster and secure using your fingerprint on supported devices.', '2026-03-20 18:12:11', NULL);
INSERT INTO `help_page_content` (`id`, `common_issues`, `additional_resources`, `updated_at`, `updated_by`) VALUES
(1, 'Cannot log in — check your student ID and password.\r\nVoting page not loading — ensure stable internet connection.\r\nBrowser compatibility issues — try Chrome or Edge.\r\nFingerprint login not working — register fingerprint in your dashboard.\r\nAlready voted status — ensure you are logged in with your correct account.\r\n', NULL, '2026-03-14 16:12:12', 1);
